impl Solution{pub fn four_sum(mut a:Vec<i32>,t:i32)->Vec<Vec<i32>>{a.sort_unstable();let n=a.len();let mut o=vec![];for i in 0..n.saturating_sub(3){if i>0&&a[i]==a[i-1]{continue}for j in i+1..n.saturating_sub(2){if j>i+1&&a[j]==a[j-1]{continue}let(mut l,mut r)=(j+1,n-1);while l<r{let s=a[i]as i64+a[j]as i64+a[l]as i64+a[r]as i64;if s<t as i64{l+=1}else if s>t as i64{r-=1}else{o.push(vec![a[i],a[j],a[l],a[r]]);let(x,y)=(a[l],a[r]);while l<r&&a[l]==x{l+=1}while l<r&&a[r]==y{r-=1}}}}}o}}
